package coverage

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestStripCoverageBanner(t *testing.T) {
	in := strings.Join([]string{
		"# Title",
		"> Generated by something",
		"see update-api-coverage.py",
		"run CBDEV DOCS COVERAGE now",
		"then re-run `make docs`.",
		"keep me",
	}, "\n")
	if got, want := stripCoverageBanner(in), "# Title\nkeep me"; got != want {
		t.Fatalf("got %q want %q", got, want)
	}
}

func TestFirstDiffSample(t *testing.T) {
	tests := []struct {
		name, a, b string
		n          int
		want       []string
		notWant    []string
	}{
		{"middle", "x\ny\nz", "x\nY\nz", 2, []string{"first diverge near line 2:", "- y\n+ Y\n", "- z\n+ z\n"}, nil},
		{"a longer", "x\ny", "x", 3, []string{"near line 2:", "- y\n"}, []string{"+ "}},
		{"b longer", "x", "x\nq", 1, []string{"near line 2:", "+ q\n"}, []string{"- "}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := firstDiffSample(tc.a, tc.b, tc.n)
			for _, s := range tc.want {
				if !strings.Contains(got, s) {
					t.Errorf("missing %q in %q", s, got)
				}
			}
			for _, s := range tc.notWant {
				if strings.Contains(got, s) {
					t.Errorf("unexpected %q in %q", s, got)
				}
			}
		})
	}
}

func TestCompareWithErrors(t *testing.T) {
	tests := []struct {
		name    string
		opts    func(t *testing.T) CompareOptions
		wantErr string
	}{
		{"missing dirs", func(*testing.T) CompareOptions { return CompareOptions{} }, "backlog root and --compare-with dir are required"},
		{"missing snapshot", func(t *testing.T) CompareOptions {
			return CompareOptions{BacklogRoot: t.TempDir(), CapellaDocs: t.TempDir()}
		}, "management-api-v4.0-operations.json"},
		{"missing capellactl report", func(t *testing.T) CompareOptions {
			return CompareOptions{BacklogRoot: backlogDir(t), CapellaDocs: t.TempDir()}
		}, "read capellactl release-1.0.0/API-COVERAGE.md"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := CompareWith(tc.opts(t))
			if err == nil || !strings.Contains(err.Error(), tc.wantErr) {
				t.Fatalf("got %v, want %q", err, tc.wantErr)
			}
		})
	}
}

func TestCompareWithReportsDiffs(t *testing.T) {
	theirs := t.TempDir()
	for _, rel := range []string{
		"release-1.0.0/API-COVERAGE.md",
		"release-1.5.0/API-COVERAGE.md",
		"release-2.0.0/API-COVERAGE-APP-SERVICES.md",
	} {
		p := filepath.Join(theirs, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte("# Not the real report\n"), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	res, err := CompareWith(CompareOptions{BacklogRoot: backlogDir(t), CapellaDocs: theirs, InProgressIDs: []string{"CAP-032"}})
	if err != nil {
		t.Fatal(err)
	}
	if len(res.Reports) != 3 {
		t.Fatalf("want 3 reports, got %d", len(res.Reports))
	}
	for _, r := range res.Reports {
		if !r.Differs || r.TheirLines != 2 || r.OursLines <= r.TheirLines {
			t.Errorf("%s: unexpected diff summary %+v", r.Name, r)
		}
		if !strings.Contains(r.Sample, "first diverge near line 1:") || !strings.Contains(r.Sample, "- # Not the real report") {
			t.Errorf("%s: sample %q", r.Name, r.Sample)
		}
	}
}
